import{_ as t,o as a,c as r,a0 as l}from"./chunks/framework.DYAX5gPL.js";const c=JSON.parse('{"title":"Symbol 样式","description":"","frontmatter":{"title":"Symbol 样式"},"headers":[],"relativePath":"guide/style/symbols.md","filePath":"guide/style/symbols.md"}'),o={name:"guide/style/symbols.md"};function n(i,e,h,s,p,d){return a(),r("div",null,[...e[0]||(e[0]=[l(`<h1 id="symbol样式文档" tabindex="-1">Symbol样式文档 <a class="header-anchor" href="#symbol样式文档" aria-label="Permalink to &quot;Symbol样式文档&quot;">​</a></h1><p>矢量的Symbol样式分为以下几个大类：</p><ul><li><a href="#marker样式属性">marker样式属性</a>，定义了图标相关样式属性</li><li><a href="#text样式属性">text样式属性</a>，定义了文字相关样式属性</li><li><a href="#line样式属性">line样式属性</a>，定义了线相关的样式属性</li><li><a href="#polygon样式属性">polygon样式属性</a>，定义了面相关的样式属性。</li></ul><p>本文档包含了矢量的样式属性，三维的样式由渲染材质定义，具体请参考<a href="/guide/style/material.html">材质说明文档</a>。</p><h2 id="marker样式属性" tabindex="-1">marker样式属性 <a class="header-anchor" href="#marker样式属性" aria-label="Permalink to &quot;marker样式属性&quot;">​</a></h2><p>marker样式属性分为以下几类：</p><ul><li>基础属性：图标最常用的样式属性</li><li>矢量图标：<a href="https://maptalks.org/examples/cn/style/vector-marker/#style_vector-marker" target="_blank" rel="noreferrer">矢量图标</a>可以调整的样式属性</li><li>对齐：如何让图标与坐标点对齐的属性设置</li><li>分布：图标是否沿线分布及分布方式的设置</li><li>碰撞检测：碰撞检测相关设置</li><li>三维透视：三维透视相关的属性</li><li>文字自适应：图标高宽自动适应文字的相关样式属性</li></ul><table tabindex="0"><thead><tr><th>类别</th><th>属性</th></tr></thead><tbody><tr><td>基础属性</td><td>markerFile, markerOpacity, markerWidth, markerHeight, markerDx, markerDy, markerRotation</td></tr><tr><td>对齐</td><td>markerVerticalAlignment, markerHorizontalAlignment, markerRotationAlignment, markerPitchAlignment</td></tr><tr><td>分布</td><td>markerPlacement*, markerSpacing, mergeOnProperty</td></tr><tr><td>碰撞检测</td><td>markerAllowOverlap, markerIgnorePlacement</td></tr><tr><td>三维透视</td><td>markerPerspectiveRatio*</td></tr><tr><td>文字自适应</td><td>markerTextFit, markerTextFitPadding</td></tr><tr><td>矢量图标</td><td>markerType, markerFill, markerFillPatternFile, markerFillOpacity, markerLineColor, markerLineWidth, markerLineOpacity, markerLineDasharray, markerLinePatternFile</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>属性名上带*号的，表示该属性不支持<a href="/guide/style/function-type.html">function-type</a>。</p></div><hr><h3 id="markerfile" tabindex="-1">markerFile <a class="header-anchor" href="#markerfile" aria-label="Permalink to &quot;markerFile&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，图标的地址，支持url或者base64字符串。</p><hr><h3 id="markeropacity" tabindex="-1">markerOpacity <a class="header-anchor" href="#markeropacity" aria-label="Permalink to &quot;markerOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong>，取值范围0-1，图标透明度</p><hr><h3 id="markerwidth" tabindex="-1">markerWidth <a class="header-anchor" href="#markerwidth" aria-label="Permalink to &quot;markerWidth&quot;">​</a></h3><p>默认值：15</p><p><strong>Number</strong>，取值范围0-254，图标宽度</p><hr><h3 id="markerheight" tabindex="-1">markerHeight <a class="header-anchor" href="#markerheight" aria-label="Permalink to &quot;markerHeight&quot;">​</a></h3><p>默认值：15</p><p><strong>Number</strong>，取值范围0-254，图标高度</p><hr><h3 id="markerdx" tabindex="-1">markerDx <a class="header-anchor" href="#markerdx" aria-label="Permalink to &quot;markerDx&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，取值范围0-127，图标在屏幕范围x轴上的偏移量</p><hr><h3 id="markerdy" tabindex="-1">markerDy <a class="header-anchor" href="#markerdy" aria-label="Permalink to &quot;markerDy&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，取值范围0-127，图标在屏幕范围y轴上的偏移量</p><hr><h3 id="markerrotation" tabindex="-1">markerRotation <a class="header-anchor" href="#markerrotation" aria-label="Permalink to &quot;markerRotation&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，取值范围0-360，图标的旋转角度，单位度</p><hr><h3 id="markerhorizontalalignment" tabindex="-1">markerHorizontalAlignment <a class="header-anchor" href="#markerhorizontalalignment" aria-label="Permalink to &quot;markerHorizontalAlignment&quot;">​</a></h3><p>默认值：middle</p><p><strong>String</strong>，图标相对坐标点的水平对齐方式，取值范围： left, middle, right</p><hr><h3 id="markerverticalalignment" tabindex="-1">markerVerticalAlignment <a class="header-anchor" href="#markerverticalalignment" aria-label="Permalink to &quot;markerVerticalAlignment&quot;">​</a></h3><p>默认值：middle</p><p><strong>String</strong>，图标相对坐标点的垂直对齐方式，取值范围： top, middle, bottom</p><hr><h3 id="markerrotationalignment" tabindex="-1">markerRotationAlignment <a class="header-anchor" href="#markerrotationalignment" aria-label="Permalink to &quot;markerRotationAlignment&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，如果设为map，则图标自动随地图旋转而旋转。</p><hr><h3 id="markerpitchalignment" tabindex="-1">markerPitchAlignment <a class="header-anchor" href="#markerpitchalignment" aria-label="Permalink to &quot;markerPitchAlignment&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，如果设为map，则图标自动随地图倾斜而倾斜。</p><hr><h3 id="markerplacement" tabindex="-1">markerPlacement <a class="header-anchor" href="#markerplacement" aria-label="Permalink to &quot;markerPlacement&quot;">​</a></h3><p>默认值：point</p><p>不支持function-type</p><p><strong>String</strong>，图标的分布方式，沿线分布还是正常点分布，可选的值：point，line</p><p>如果数据是线，且markerPlacement为point时，取的是线的第一个端点的坐标。</p><p>如果数据是线，且markerPlacement为line时，沿线每隔markerSpacing取一个坐标。</p><p>如果数据是面，且markerPlacement为point时，则取面的可达性极点位置，即使面是凹多边形，该点也一定在面的内部。</p><hr><h3 id="markerspacing" tabindex="-1">markerSpacing <a class="header-anchor" href="#markerspacing" aria-label="Permalink to &quot;markerSpacing&quot;">​</a></h3><p>默认值：250</p><p><strong>Number</strong>，markerPlacement必须是line。即图标沿线分布时，相互的间隔，单位像素。</p><hr><h3 id="mergeonproperty" tabindex="-1">mergeOnProperty <a class="header-anchor" href="#mergeonproperty" aria-label="Permalink to &quot;mergeOnProperty&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，markerPlacement必须是line。是否按照给定property属性合并该属性的值相同的line，能让沿线分布的图标绘制得更加准确，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mergeOnProperty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;road_name&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h3 id="markerallowoverlap" tabindex="-1">markerAllowOverlap <a class="header-anchor" href="#markerallowoverlap" aria-label="Permalink to &quot;markerAllowOverlap&quot;">​</a></h3><p>默认值：false</p><p><strong>Boolean</strong>，必须开启碰撞检测。当此图标与其他图标碰撞时，是否仍然允许该图标显示。</p><hr><h3 id="markerignoreplacement" tabindex="-1">markerIgnorePlacement <a class="header-anchor" href="#markerignoreplacement" aria-label="Permalink to &quot;markerIgnorePlacement&quot;">​</a></h3><p>默认值：false</p><p><strong>Boolean</strong>，必须开启碰撞检测。当此图标与其他图标碰撞时，是否仍然允许其他图标显示。</p><hr><h3 id="markerperspectiveratio" tabindex="-1">markerPerspectiveRatio <a class="header-anchor" href="#markerperspectiveratio" aria-label="Permalink to &quot;markerPerspectiveRatio&quot;">​</a></h3><p>默认值：true</p><p>不支持function-type</p><p><strong>Boolean</strong>，是否开启三维透视，图标的近大远小效果。</p><hr><h3 id="markertextfit" tabindex="-1">markerTextFit <a class="header-anchor" href="#markertextfit" aria-label="Permalink to &quot;markerTextFit&quot;">​</a></h3><p>默认值： none</p><p><strong>String</strong>，必须设置textName。图标是否根据文字来自动设置自身的高度和宽度，可选值： both（高宽都自适应）, width（仅宽度自适应）, height（仅高度自适应）</p><hr><h3 id="markertextfitpadding" tabindex="-1">markerTextFitPadding <a class="header-anchor" href="#markertextfitpadding" aria-label="Permalink to &quot;markerTextFitPadding&quot;">​</a></h3><p>默认值：[0, 0, 0, 0]</p><p><strong>Number[]</strong>，必须设置文字且markerTextFit必须为true。四位数组，单位像素，图标上下左右四边距离文字的padding，四位数字的含义是[上边，右边，下边，左边]</p><hr><h3 id="markertype" tabindex="-1">markerType <a class="header-anchor" href="#markertype" aria-label="Permalink to &quot;markerType&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong> 矢量图标类别，可选的值： ellipse, cross, x, diamond, bar, square, triangle, pin, pie, rectangle</p><hr><h3 id="markerfill" tabindex="-1">markerFill <a class="header-anchor" href="#markerfill" aria-label="Permalink to &quot;markerFill&quot;">​</a></h3><p>默认值：#00f</p><p><strong>String</strong>|<strong>Number[]</strong>，必须有合法的markerType。矢量图标的填充色，可以为<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者归一化四位数组。</p><hr><h3 id="markerfillpatternfile" tabindex="-1">markerFillPatternFile <a class="header-anchor" href="#markerfillpatternfile" aria-label="Permalink to &quot;markerFillPatternFile&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，必须有合法的markerType。矢量图标的模式填充图片地址，支持url或者base64字符串。</p><hr><h3 id="markerfillopacity" tabindex="-1">markerFillOpacity <a class="header-anchor" href="#markerfillopacity" aria-label="Permalink to &quot;markerFillOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong>，必须有合法的markerType。矢量图标填充透明度，取值范围0-1。</p><hr><h3 id="markerlinecolor" tabindex="-1">markerLineColor <a class="header-anchor" href="#markerlinecolor" aria-label="Permalink to &quot;markerLineColor&quot;">​</a></h3><p>默认值：#000</p><p><strong>String</strong>|<strong>Number[]</strong>，必须有合法的markerType。矢量图标边框颜色，可以为<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者归一化四位数组。</p><hr><h3 id="markerlinewidth" tabindex="-1">markerLineWidth <a class="header-anchor" href="#markerlinewidth" aria-label="Permalink to &quot;markerLineWidth&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong>，必须有合法的markerType。矢量图标边框线宽。</p><hr><h3 id="markerlineopacity" tabindex="-1">markerLineOpacity <a class="header-anchor" href="#markerlineopacity" aria-label="Permalink to &quot;markerLineOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong>，必须有合法的markerType。矢量图标边框透明度，取值范围0-1。</p><hr><h3 id="markerlinedasharray" tabindex="-1">markerLineDasharray <a class="header-anchor" href="#markerlinedasharray" aria-label="Permalink to &quot;markerLineDasharray&quot;">​</a></h3><p>默认值：[]</p><blockquote><p>注：默认值以 2026 源码为准为 []（空数组，即实线，maptalks 核心默认），旧文档写作 1 有误。</p></blockquote><p><strong>Number[]</strong>，必须有合法的markerType。矢量图标边框虚线样式，与canvas.setLineDash方法支持的虚线样式相同。</p><hr><h3 id="markerlinepatternfile" tabindex="-1">markerLinePatternFile <a class="header-anchor" href="#markerlinepatternfile" aria-label="Permalink to &quot;markerLinePatternFile&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，必须有合法的markerType。矢量图标边框的模式填充图片地址，支持url或者base64字符串。</p><hr><h2 id="text样式属性" tabindex="-1">text样式属性 <a class="header-anchor" href="#text样式属性" aria-label="Permalink to &quot;text样式属性&quot;">​</a></h2><p>text样式属性分为以下几类：</p><ul><li>基础属性：文字最常用的样式属性</li><li>文字描边：文字描边的相关属性</li><li>对齐：如何让文字与坐标点对齐的设置</li><li>碰撞检测：碰撞检测相关设置</li><li>三维透视：三维透视相关的属性</li></ul><table tabindex="0"><thead><tr><th>类别</th><th>属性</th></tr></thead><tbody><tr><td>基础属性</td><td>textName, textSize, textFill, textOpacity, textFaceName, textWeight, textStyle, textRotation, textDx, textDy, textWrapWidth</td></tr><tr><td>文字描边</td><td>textHaloFill, textHaloRadius, textHaloOpacity, textHaloBlur</td></tr><tr><td>对齐</td><td>textHorizontalAlignment, textVerticalAlignment, textRotationAlignment, textPitchAlignment</td></tr><tr><td>分布</td><td>textPlacement*, textSpacing, mergeOnProperty</td></tr><tr><td>碰撞检测</td><td>textAllowOverlap, textIgnorePlacement</td></tr><tr><td>三维透视</td><td>textPerspectiveRatio*</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>属性名上带*号的，表示该属性不支持<a href="/guide/style/function-type.html">function-type</a>。</p></div><hr><h3 id="textname" tabindex="-1">textName <a class="header-anchor" href="#textname" aria-label="Permalink to &quot;textName&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，显示的文字内容，如果要显示某个属性得值，用大括号括起来即可，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 用name属性的值作为文字内容</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;textName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{name}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h3 id="textsize" tabindex="-1">textSize <a class="header-anchor" href="#textsize" aria-label="Permalink to &quot;textSize&quot;">​</a></h3><p>默认值：14</p><p><strong>Number</strong>，文字大小。</p><hr><h3 id="textfill" tabindex="-1">textFill <a class="header-anchor" href="#textfill" aria-label="Permalink to &quot;textFill&quot;">​</a></h3><p>默认值：[0, 0, 0, 1]</p><blockquote><p>注：默认值以 2026 源码为准为 [0, 0, 0, 1]（黑色不透明，vt create_text_painter DEFAULT_UNIFORMS），旧文档写作 [0, 0, 0, 0] 有误。</p></blockquote><p><strong>String</strong> | <strong>Number</strong>，文字颜色，可以是<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者四位归一化数组。</p><hr><h3 id="textopacity" tabindex="-1">textOpacity <a class="header-anchor" href="#textopacity" aria-label="Permalink to &quot;textOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong>，文字透明度，取值范围0-1。</p><hr><h3 id="textfacename" tabindex="-1">textFaceName <a class="header-anchor" href="#textfacename" aria-label="Permalink to &quot;textFaceName&quot;">​</a></h3><p>默认值：monospace</p><p><strong>String</strong>，文字字体，与css的<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/font-family" target="_blank" rel="noreferrer">font-family</a>定义相同。</p><hr><h3 id="textweight" tabindex="-1">textWeight <a class="header-anchor" href="#textweight" aria-label="Permalink to &quot;textWeight&quot;">​</a></h3><p>默认值：normal</p><blockquote><p>注：默认值以 2026 源码为准为 &#39;normal&#39;（数值上与 400 等价，maptalks 核心 TextMarkerSymbolizer 默认），旧文档写作 400。</p></blockquote><p><strong>String</strong>，文字字重，与css的<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/font-weight" target="_blank" rel="noreferrer">font-weight</a>定义相同。</p><hr><h3 id="textstyle" tabindex="-1">textStyle <a class="header-anchor" href="#textstyle" aria-label="Permalink to &quot;textStyle&quot;">​</a></h3><p>默认值：normal</p><p><strong>String</strong>，文字风格，支持斜体等，与css<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/font-style" target="_blank" rel="noreferrer">font-style</a>定义相同。</p><hr><h3 id="textrotation" tabindex="-1">textRotation <a class="header-anchor" href="#textrotation" aria-label="Permalink to &quot;textRotation&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，文字旋转角度，0-360，单位度。</p><hr><h3 id="textdx" tabindex="-1">textDx <a class="header-anchor" href="#textdx" aria-label="Permalink to &quot;textDx&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，文字在屏幕x轴上的偏移度，单位像素。</p><hr><h3 id="textdy" tabindex="-1">textDy <a class="header-anchor" href="#textdy" aria-label="Permalink to &quot;textDy&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，文字在屏幕y轴上的偏移度，单位像素。</p><hr><h3 id="textwrapwidth" tabindex="-1">textWrapWidth <a class="header-anchor" href="#textwrapwidth" aria-label="Permalink to &quot;textWrapWidth&quot;">​</a></h3><p>默认值：240</p><p><strong>Number</strong> 文字换行长度，即文字长度超过该值时就会自动换行。</p><hr><h3 id="texthalofill" tabindex="-1">textHaloFill <a class="header-anchor" href="#texthalofill" aria-label="Permalink to &quot;textHaloFill&quot;">​</a></h3><p>默认值：[1, 1, 1, 1]</p><p><strong>String</strong> | <strong>Number[]</strong>，文字描边颜色，可以是<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者四位归一化数组。</p><hr><h3 id="texthaloradius" tabindex="-1">textHaloRadius <a class="header-anchor" href="#texthaloradius" aria-label="Permalink to &quot;textHaloRadius&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，文字描边半径。</p><hr><h3 id="texthaloopacity" tabindex="-1">textHaloOpacity <a class="header-anchor" href="#texthaloopacity" aria-label="Permalink to &quot;textHaloOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong>，文字描边透明度，取值范围0-1。</p><hr><h3 id="texthaloblur" tabindex="-1">textHaloBlur <a class="header-anchor" href="#texthaloblur" aria-label="Permalink to &quot;textHaloBlur&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>， 文字描边的清晰度。</p><hr><h3 id="texthorizontalalignment" tabindex="-1">textHorizontalAlignment <a class="header-anchor" href="#texthorizontalalignment" aria-label="Permalink to &quot;textHorizontalAlignment&quot;">​</a></h3><p>默认值：middle</p><p><strong>String</strong>，文字相对坐标点的水平对齐方式，取值范围： left, middle, right</p><hr><h3 id="textverticalalignment" tabindex="-1">textVerticalAlignment <a class="header-anchor" href="#textverticalalignment" aria-label="Permalink to &quot;textVerticalAlignment&quot;">​</a></h3><p>默认值：middle</p><p><strong>String</strong>，文字相对坐标点的垂直对齐方式，取值范围： top, middle, bottom</p><hr><h3 id="textrotationalignment" tabindex="-1">textRotationAlignment <a class="header-anchor" href="#textrotationalignment" aria-label="Permalink to &quot;textRotationAlignment&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，如果设为map，则文字自动随地图旋转而旋转。</p><hr><h3 id="textpitchalignment" tabindex="-1">textPitchAlignment <a class="header-anchor" href="#textpitchalignment" aria-label="Permalink to &quot;textPitchAlignment&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，如果设为map，则文字自动随地图倾斜而倾斜。</p><hr><h3 id="textplacement" tabindex="-1">textPlacement <a class="header-anchor" href="#textplacement" aria-label="Permalink to &quot;textPlacement&quot;">​</a></h3><p>默认值：point</p><p>不支持function-type</p><p><strong>String</strong>，文字的分布方式，沿线分布还是正常点分布，可选的值：point，line，如果是icon渲染插件，且设置过markerPlacement，则被markerPlacement的值替代。</p><p>如果数据是线，且textPlacement为point时，取的是线的第一个端点的坐标。</p><p>如果数据是线，且textPlacement为line时，沿线每隔textSpacing取一个坐标。</p><p>如果数据是面，且textPlacement为point时，则取面的可达性极点位置，即使面是凹多边形，该点也一定在面的内部。</p><hr><h3 id="textspacing" tabindex="-1">textSpacing <a class="header-anchor" href="#textspacing" aria-label="Permalink to &quot;textSpacing&quot;">​</a></h3><p>默认值：250</p><p><strong>Number</strong>，textPlacement必须是line。即文字沿线分布时，相互的间隔，单位像素，如果是icon渲染插件，且设置过markerSpacing，则被markerSpacing的值替代。</p><hr><h3 id="mergeonproperty-1" tabindex="-1">mergeOnProperty <a class="header-anchor" href="#mergeonproperty-1" aria-label="Permalink to &quot;mergeOnProperty&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，textPlacement必须是line。是否按照给定property属性合并该属性的值相同的line，能让沿线分布的文字绘制得更加准确，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mergeOnProperty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;road_name&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h3 id="textallowoverlap" tabindex="-1">textAllowOverlap <a class="header-anchor" href="#textallowoverlap" aria-label="Permalink to &quot;textAllowOverlap&quot;">​</a></h3><p>默认值：false</p><p><strong>Boolean</strong>，必须开启碰撞检测。当此文字与其他文字碰撞时，是否仍然允许该文字显示。</p><hr><h3 id="textignoreplacement" tabindex="-1">textIgnorePlacement <a class="header-anchor" href="#textignoreplacement" aria-label="Permalink to &quot;textIgnorePlacement&quot;">​</a></h3><p>默认值：false</p><p><strong>Boolean</strong>，必须开启碰撞检测。当此文字与其他文字碰撞时，是否仍然允许其他文字显示。</p><hr><h3 id="textperspectiveratio" tabindex="-1">textPerspectiveRatio <a class="header-anchor" href="#textperspectiveratio" aria-label="Permalink to &quot;textPerspectiveRatio&quot;">​</a></h3><p>默认值：0</p><p>不支持function-type</p><p><strong>Number</strong>，文字的透视比率，取值范围 0 - 1，0 表示不开启三维透视（默认），数值越大，近大远小效果越明显（vt create_text_painter 默认 uniform 为 0，textPlacement 为 line 时默认为 1）。</p><blockquote><p>注：旧文档将 textPerspectiveRatio 描述为默认 true 的 Boolean，2026 源码中为 0-1 的数值比率，默认 0（2026 核对）。</p></blockquote><hr><h2 id="line样式属性" tabindex="-1">line样式属性 <a class="header-anchor" href="#line样式属性" aria-label="Permalink to &quot;line样式属性&quot;">​</a></h2><hr><h3 id="linecolor" tabindex="-1">lineColor <a class="header-anchor" href="#linecolor" aria-label="Permalink to &quot;lineColor&quot;">​</a></h3><p>默认值: #fff</p><blockquote><p>注：默认值以 2026 源码为准为白色 #fff（vt LinePainter 为配合 linePattern 合成把默认线色设为白色，见源码注释），旧文档写作 #000。</p></blockquote><p><strong>String</strong> | <strong>Number[]</strong> 线的颜色，可以为<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者归一化四位数组。</p><hr><h3 id="linewidth" tabindex="-1">lineWidth <a class="header-anchor" href="#linewidth" aria-label="Permalink to &quot;lineWidth&quot;">​</a></h3><p>默认值：2</p><p><strong>Number</strong> 线宽，取值范围 0 - 127。</p><hr><h3 id="lineopacity" tabindex="-1">lineOpacity <a class="header-anchor" href="#lineopacity" aria-label="Permalink to &quot;lineOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong> 线的透明度，取值范围 0 - 1。</p><hr><h3 id="linejoin" tabindex="-1">lineJoin <a class="header-anchor" href="#linejoin" aria-label="Permalink to &quot;lineJoin&quot;">​</a></h3><p>默认值：miter</p><p><strong>String</strong>，线的连接样式，可选的值：miter，round，bevel。</p><hr><h3 id="linecap" tabindex="-1">lineCap <a class="header-anchor" href="#linecap" aria-label="Permalink to &quot;lineCap&quot;">​</a></h3><p>默认值：butt</p><p><strong>String</strong>，线头的样式，可选的值：butt，round，square</p><hr><h3 id="linedx" tabindex="-1">lineDx <a class="header-anchor" href="#linedx" aria-label="Permalink to &quot;lineDx&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，线在屏幕坐标x轴上的偏移量，单位像素，取值范围：-128 - 127</p><hr><h3 id="linedy" tabindex="-1">lineDy <a class="header-anchor" href="#linedy" aria-label="Permalink to &quot;lineDy&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，线在屏幕坐标y轴上的偏移量，单位像素，取值范围：-128 - 127</p><hr><h3 id="linestrokewidth" tabindex="-1">lineStrokeWidth <a class="header-anchor" href="#linestrokewidth" aria-label="Permalink to &quot;lineStrokeWidth&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，线的描边宽度，取值范围 0 - 127。</p><hr><h3 id="linestrokecolor" tabindex="-1">lineStrokeColor <a class="header-anchor" href="#linestrokecolor" aria-label="Permalink to &quot;lineStrokeColor&quot;">​</a></h3><p>默认值: [0, 0, 0, 0]</p><blockquote><p>注：默认值以 2026 源码为准为 [0, 0, 0, 0]（透明，即默认不绘制描边），旧文档写作 #000。</p></blockquote><p><strong>String</strong> | <strong>Number[]</strong> 线的描边的颜色，可以为<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者归一化四位数组。</p><hr><h3 id="linepatternfile" tabindex="-1">linePatternFile <a class="header-anchor" href="#linepatternfile" aria-label="Permalink to &quot;linePatternFile&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，线的填充图片，支持url或者base64字符串。</p><hr><h3 id="linejoinpatternmode" tabindex="-1">lineJoinPatternMode <a class="header-anchor" href="#linejoinpatternmode" aria-label="Permalink to &quot;lineJoinPatternMode&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，lineJoin处的模型填充方式，为0时，则lineJoin为连续绘制纹理，为1时，则设为图片第一个像素处的颜色。</p><blockquote><p>注：lineJoinPatternMode 在 2026 源码（vt 包全仓库 grep）中已不存在，为旧版属性，不再生效（2026 核对）。</p></blockquote><hr><h3 id="linepatterngap" tabindex="-1">linePatternGap <a class="header-anchor" href="#linepatterngap" aria-label="Permalink to &quot;linePatternGap&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，填充图片之间的间隔宽度，单位为填充图片宽度的倍数，例如设为1时，相邻两张填充图片之间的间隔为填充图片的宽度。</p><hr><h3 id="linepatternanimspeed" tabindex="-1">linePatternAnimSpeed <a class="header-anchor" href="#linepatternanimspeed" aria-label="Permalink to &quot;linePatternAnimSpeed&quot;">​</a></h3><p>默认值：0</p><p><strong>Number</strong>，动画速度，取值范围-5到5，为负数时，动画方向会变为反向的。</p><blockquote><p>注：原文档的&quot;线的动画&quot;示意图（assets/line-animation.gif）在迁移源中缺失，暂未收录（2026 核对）。</p></blockquote><hr><h3 id="linedasharray" tabindex="-1">lineDasharray <a class="header-anchor" href="#linedasharray" aria-label="Permalink to &quot;lineDasharray&quot;">​</a></h3><p>默认值：[0, 0, 0, 0]</p><p><strong>Number[]</strong> 线的虚线样式，四位数组，单位像素，含义类似canvas的setLineDash，但只支持四位。</p><hr><h3 id="linedashcolor" tabindex="-1">lineDashColor <a class="header-anchor" href="#linedashcolor" aria-label="Permalink to &quot;lineDashColor&quot;">​</a></h3><p>默认值: [0, 0, 0, 0]</p><p><strong>String</strong> | <strong>Number[]</strong>，线虚线的颜色，可以为<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者归一化四位数组。</p><h2 id="polygon样式属性" tabindex="-1">polygon样式属性 <a class="header-anchor" href="#polygon样式属性" aria-label="Permalink to &quot;polygon样式属性&quot;">​</a></h2><hr><h3 id="polygonfill" tabindex="-1">polygonFill <a class="header-anchor" href="#polygonfill" aria-label="Permalink to &quot;polygonFill&quot;">​</a></h3><p>默认值: #fff</p><p><strong>String</strong> | <strong>Number[]</strong> 面的填充色，可以为<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/color_value" target="_blank" rel="noreferrer">css颜色值</a>或者归一化四位数组。</p><hr><h3 id="polygonopacity" tabindex="-1">polygonOpacity <a class="header-anchor" href="#polygonopacity" aria-label="Permalink to &quot;polygonOpacity&quot;">​</a></h3><p>默认值：1</p><p><strong>Number</strong> 面的填充色透明度，取值范围 0 - 1。</p><hr><h3 id="polygonpatternfile" tabindex="-1">polygonPatternFile <a class="header-anchor" href="#polygonpatternfile" aria-label="Permalink to &quot;polygonPatternFile&quot;">​</a></h3><p>默认值：null</p><p><strong>String</strong>，面的填充图片，支持url或者base64字符串。</p><hr><h3 id="uvscale" tabindex="-1">uvScale <a class="header-anchor" href="#uvscale" aria-label="Permalink to &quot;uvScale&quot;">​</a></h3><p>默认值：[1, 1]</p><p><strong>Number[]</strong>，纹理的缩放倍数，两位数组。</p><hr><h3 id="uvoffset" tabindex="-1">uvOffset <a class="header-anchor" href="#uvoffset" aria-label="Permalink to &quot;uvOffset&quot;">​</a></h3><p>默认值：[0, 0]</p><blockquote><p>注：uvOffset 默认值已按 2026 源码调整为 [0, 0]（FillPainter DEFAULT_UNIFORMS / PolygonLayer 默认），旧文档写作 [0, 1]。</p></blockquote><p><strong>Number[]</strong>，两位数组，纹理的偏移量，0表示不偏移，1表示偏移量等于图片的尺寸，例如0.5表示偏移到图片的一半。</p><h2 id="_2026-新增" tabindex="-1">2026 新增 <a class="header-anchor" href="#_2026-新增" aria-label="Permalink to &quot;2026 新增&quot;">​</a></h2><p>以下 symbol 属性为 2026 源码（@maptalks/gl-layers vt 包）中新增或补充，旧版文档未收录：</p><h3 id="watersymbol-water-渲染插件" tabindex="-1">WaterSymbol（water 渲染插件） <a class="header-anchor" href="#watersymbol-water-渲染插件" aria-label="Permalink to &quot;WaterSymbol（water 渲染插件）&quot;">​</a></h3><p>用于 water 渲染插件（真实水体），新增于 2026 源码：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>ssr</td><td>Boolean</td><td>屏幕空间反射</td></tr><tr><td>texWaveNormal</td><td>String</td><td>波浪法线贴图</td></tr><tr><td>texWavePerturbation</td><td>String</td><td>波浪扰动贴图</td></tr><tr><td>waterBaseColor</td><td>Number[]</td><td>水面基础色</td></tr><tr><td>contrast</td><td>Number</td><td>对比度</td></tr><tr><td>hsv</td><td>Number[]</td><td>HSV 调整</td></tr><tr><td>uvScale</td><td>Number</td><td>UV 缩放</td></tr><tr><td>animation</td><td>Boolean</td><td>波浪动画</td></tr><tr><td>waterSpeed</td><td>Number</td><td>水流速度</td></tr><tr><td>waterDirection</td><td>Number</td><td>水流方向</td></tr></tbody></table><blockquote><p>注：water 符号的默认值（2026 源码 WaterPainter）：ssr 默认 false，texWaveNormal / texWavePerturbation 默认 null，waterBaseColor 默认 [0.1451, 0.2588, 0.4863, 1]，contrast 默认 1，hsv 默认 [0, 0, 0]，uvScale 默认 3，animation 默认 false，waterSpeed 默认 1，waterDirection 默认 0。</p></blockquote><h3 id="litsymbol-lit-渲染插件" tabindex="-1">LitSymbol（lit 渲染插件） <a class="header-anchor" href="#litsymbol-lit-渲染插件" aria-label="Permalink to &quot;LitSymbol（lit 渲染插件）&quot;">​</a></h3><p>lit 渲染插件（pbr 材质三维渲染）的 symbol，新增于 2026 源码：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>bloom</td><td>Boolean</td><td>是否辉光</td></tr><tr><td>ssr</td><td>Boolean</td><td>屏幕空间反射</td></tr><tr><td>polygonOpacity</td><td>Number</td><td>多边形不透明度</td></tr><tr><td>material</td><td>Object</td><td>PBR 材质（LitMaterial），字段见<a href="/guide/style/material.html">材质说明文档</a></td></tr></tbody></table><h3 id="polygonlayer-extrudepolygonlayer-补充" tabindex="-1">PolygonLayer / ExtrudePolygonLayer 补充 <a class="header-anchor" href="#polygonlayer-extrudepolygonlayer-补充" aria-label="Permalink to &quot;PolygonLayer / ExtrudePolygonLayer 补充&quot;">​</a></h3><ul><li><code>uvOffsetInMeter</code>（Boolean，默认 false）：uv 偏移是否按米计。</li><li><code>polygonPatternFileWidth</code> / <code>polygonPatternFileHeight</code> / <code>polygonPatternFileOrigin</code>：填充纹理的宽、高与原点设置。</li><li><code>polygonPatternUV</code>：填充纹理的 uv 控制。</li><li>ExtrudePolygonLayer 的顶面/底面颜色：<code>topPolygonFill</code>、<code>bottomPolygonFill</code>（默认 [1, 1, 1, 1]）。</li></ul><blockquote><p>本文档已与 @maptalks/gl-layers 2026 源码核对（api-notes-vt-gl.md）</p></blockquote>`,344)])])}const g=t(o,[["render",n]]);export{c as __pageData,g as default};
